 const getToken=async()=>{if(!auth)throw new Error('Authentication is not configured.');const current=await auth.getSession();if(!current?.data?.session||!current?.data?.user)throw new Error('Your sign-in session is no longer active. Please sign in again.');const tokenUrl=AUTH_URL.replace(/\/$/,'')+'/token';let response:Response;try{response=await fetch(tokenUrl,{method:'GET',credentials:'include',cache:'no-store',headers:{Accept:'application/json'}})}catch(error){console.error('[NYIL AUTH DIAGNOSTIC]',{stage:'direct JWT token endpoint',networkError:true,errorName:error instanceof Error?error.name:'unknown'});throw new Error('Could not reach the Neon Auth token endpoint. Check the browser connection and Auth CORS settings, then try again.')}const payload=await response.json().catch(()=>null) as {token?:unknown;message?:string;error?:string}|null;const token=typeof payload?.token==='string'?payload.token:null;if(!response.ok||!token){const responseKeys=payload&&typeof payload==='object'?Object.keys(payload):[];console.error('[NYIL AUTH DIAGNOSTIC]',{stage:'direct JWT token endpoint',httpStatus:response.status,responseKeys,tokenPresent:Boolean(token)});throw new Error('Neon Auth token endpoint did not return a JWT (HTTP '+response.status+'). Response fields ['+responseKeys.join(', ')+'].')}return token}
