 const signIn=async(e:React.FormEvent)=>{
  e.preventDefault();
  if(authSubmitting)return;
  setAuthError('');
  setResetMessage('');
  if(!auth){setAuthError('Neon Auth is unavailable. Refresh the page and try again.');return}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())){setAuthError('Enter a valid team email address.');return}
  if(!password){setAuthError('Enter your password to sign in.');return}
  setAuthSubmitting(true);
  let diagnosticStage='starting';
  try{
    diagnosticStage='sending sign-in request';
    console.info('[NYIL AUTH DIAGNOSTIC]',{stage:diagnosticStage,authUrlConfigured:Boolean(AUTH_URL),emailPresent:Boolean(email.trim())});
    const r=await auth.signIn.email({email:email.trim(),password});
    console.info('[NYIL AUTH DIAGNOSTIC]',{stage:'sign-in response',hasError:Boolean(r?.error),errorMessage:r?.error?.message||null,hasData:Boolean(r?.data),redirect:Boolean((r as any)?.data?.redirect),responseKeys:r&&typeof r==='object'?Object.keys(r):[]});
    if(r?.error)throw new Error(r.error.message||'Sign in failed');
    if((r as any)?.data?.redirect){
      setAuthError('The authentication service requested a redirect, but this page did not navigate. Please share this message with support.');
      console.warn('[NYIL AUTH DIAGNOSTIC] Redirect was requested but the browser stayed on this page.');
      return;
    }
    diagnosticStage='checking session';
    const current=await auth.getSession();
    const activeSession=current?.data??null;
    console.info('[NYIL AUTH DIAGNOSTIC]',{stage:'session response',hasSession:Boolean(activeSession?.session && activeSession?.user),hasError:Boolean((current as any)?.error),errorMessage:(current as any)?.error?.message||null,sessionDataPresent:Boolean(current?.data)});
    if(!activeSession?.session || !activeSession?.user)throw new Error('Sign-in completed, but Neon Auth did not return both the user and session. Please contact support with this message.');
    setSession(activeSession);
    setAuthError('');
  }catch(err){
    const message=err instanceof Error?err.message:String(err||'Sign in failed');
    console.error('[NYIL AUTH DIAGNOSTIC]',{stage:diagnosticStage,error:message});
    setAuthError(message||'Unable to sign in. Please try again.');
  }finally{
    setAuthSubmitting(false);
  }
}
 const resetPassword=async()=>{setAuthError('');setResetMessage('');if(!auth){setAuthError('Secure sign-in is unavailable because the Neon Auth URL was not included in this build. Please contact the site administrator.');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())){setAuthError('Enter a valid email address.');return}try{const r=await auth.requestPasswordReset({email:email.trim().toLowerCase(),redirectTo:window.location.origin+'/?reset=1'});if(r?.error)throw new Error(r.error.message||'Could not send reset email');setResetMessage('If the account exists, a password reset link has been sent. Check your inbox and spam folder.')}catch(e){setAuthError((e as Error).message)}}
 const completePasswordReset=async(e:React.FormEvent)=>{e.preventDefault();setAuthError('');setResetMessage('');const params=new URLSearchParams(window.location.search);const token=params.get('token');const resetError=params.get('error');if(resetError){setAuthError('The reset link was rejected or has expired ('+resetError+'). Request a fresh reset link.');return}if(!token){setAuthError('The password reset link is invalid or expired. Request a new reset link.');return}if(password.length<8){setAuthError('Use a password with at least 8 characters.');return}if(password!==confirmPassword){setAuthError('The passwords do not match.');return}try{const r=await auth.resetPassword({newPassword:password,token});if(r?.error)throw new Error(r.error.message||'Could not reset password');window.history.replaceState({},document.title,window.location.pathname);setPassword('');setConfirmPassword('');setAuthMode('signin');setResetMessage('Password updated successfully. Sign in with your new password.')}catch(err){setAuthError((err as Error).message||'The reset link may have expired. Request a new one.')}}
 const createAdmin=async(e:React.FormEvent)=>{e.preventDefault();setAuthError('');setResetMessage('');if(!auth){setAuthError('Neon Auth is not configured in this build.');return}if(email.trim().toLowerCase()!==ADMIN_EMAIL){setAuthError('Only the authorized NYIL administrator email can be used.');return}if(password.length<8){setAuthError('Use a password with at least 8 characters.');return}if(password!==confirmPassword){setAuthError('The passwords do not match.');return}try{const r=await auth.signUp.email({email:ADMIN_EMAIL,password,name:'NYIL Administrator'});if(r?.error)throw new Error(r.error.message||'Admin account setup failed');const current=await auth.getSession();setSession(current?.data??null);setResetMessage('Admin account created.')}catch(err){setAuthError((err as Error).message+' If this admin account already exists, use “Forgot password / set password” instead.')}}
