 const save=async(e:React.FormEvent)=>{e.preventDefault();if(busy||uploading)return;const slug=form.slug.trim();if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)){setNotice('Enter a valid URL slug using lowercase English letters, numbers and hyphens (for example: my-product).');return}if(!form.category.trim()){setNotice('Product category is required.');return}if(!form.name.en.trim()||!form.summary.en.trim()){setNotice('English product name and summary are required.');setLanguage('en');return}setBusy(true);setNotice('Saving product…');try{await request(editing?'/admin/products/'+editing.id:'/admin/products',{method:editing?'PUT':'POST',body:JSON.stringify({...form,slug,image_url:form.image_urls[0]||form.image_url||''})});setEditor(false);await load();setNotice(editing?'Product updated successfully.':'Product created successfully.')}catch(e){setNotice((e as Error).message||'Product could not be saved. Please try again.')}finally{setBusy(false)}}
 const upload=async(file?:File)=>{if(!file)return;if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)){setNotice('Choose a JPEG, PNG, WebP or AVIF image.');return}if(file.size>8*1024*1024){setNotice('Image must be 8 MB or smaller.');return}setUploading(true);try{const jwt=await getToken();const r=await fetch(API_URL+'/admin/uploads',{method:'POST',headers:{Authorization:'Bearer '+jwt,'Content-Type':file.type},body:file});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Image upload failed');setForm(s=>({...s,image_urls:[...s.image_urls,d.url],image_url:s.image_urls[0]||d.url}));setNotice('Image uploaded successfully.')}catch(e){setNotice((e as Error).message)}finally{setUploading(false)}}
