  if(allowed&&!adminIdentity)return <main className="login-screen"><section className="login-card"><img src="/nyil-logo.svg" alt="NYIL"/><h1>Access restricted</h1><p>This account is not an active member of the NYIL workspace. Ask the owner to grant access.</p><button className="btn primary" onClick={()=>void signOut()}>Sign out</button></section></main>
